// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(address newLog) public {
        vm.assume(newLog != address(0));
        c.Initialized();
        bool ok;
        vm.prank(address(this));
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }
        // Rule: after initialization, SetLogFile always reverts.
        assertTrue(!ok);
    }
}
